local h = require "spec.support.helpers"
local coder = require "titan-compiler.coder"
local types = require "titan-compiler.types"

local GENERATED_HEADER_BANNER =
    "/* Generated by Titan: source foreign function interface. */"

local function with_header(contents, body)
    local path = os.tmpname() .. ".h"
    local file = assert(io.open(path, "wb"))
    assert(file:write(contents))
    assert(file:close())
    local results = table.pack(xpcall(function() return body(path) end,
        debug.traceback))
    os.remove(path)
    if not results[1] then error(results[2], 0) end
    return table.unpack(results, 2, results.n)
end

local function read_file(path)
    local file = assert(io.open(path, "rb"))
    local contents = assert(file:read("*a"))
    assert(file:close())
    return contents
end

local function cleanup()
    for _, path in ipairs({
        "test.c", "test.o", "test.so", "test.a", "test.titan.h",
    }) do
        os.remove(path)
    end
    os.execute("rm -rf test.so.dSYM")
end

describe("source-defined foreign functions", function()
    after_each(cleanup)

    it("emits one reserved companion header and the UCN entry family", function()
        with_header([[
            #ifdef TITAN_TEST_FOREIGN_HEADER_SEEN
            #error foreign header included twice in one translation unit
            #endif
            #define TITAN_TEST_FOREIGN_HEADER_SEEN 1
            typedef int ffi_int;
            typedef int (*ffi_callback)(int);
            static int ffi_apply(ffi_callback callback, int value) {
                return callback(value);
            }
        ]], function(header)
            local csrc = h.compile_and_read_c([[
                local c = foreign import "]] .. header .. [["

                foreign function add_one(input: c.ffi_int): c.ffi_int
                    return input + 1
                end

                foreign function choose(input: c.ffi_int): c.ffi_int
                    if input then return input else return 7 end
                end

                foreign function choose_or(input: c.ffi_int): c.ffi_int
                    if input then return input end
                    return 8
                end

                foreign function accumulate(limit: c.ffi_int): c.ffi_int
                    local total = 0
                    if limit then total = c.ffi_apply(add_one, total) end
                    for index = 1 as c.ffi_int, limit do
                        total = total + index
                    end
                    return total + choose(0) + choose_or(0)
                end

                local function hidden(input: integer): integer
                    do
                        if input < 0 then raise "negative" end
                    catch
                        return 0
                    end
                    return input + 2
                end

                function exercise(input: integer): integer
                    return (c.ffi_apply(add_one, input as c.ffi_int)
                        as integer) + hidden(accumulate(3) as integer)
                end
            ]])

            local generated = read_file("test.titan.h")
            assert.equal(GENERATED_HEADER_BANNER,
                generated:sub(1, #GENERATED_HEADER_BANNER))
            local add = coder._foreign_func_name("test", "add_one")
            local accumulate = coder._foreign_func_name("test", "accumulate")
            assert.truthy(add:find("\\u2133", 1, true))
            assert.truthy(generated:find("static inline ffi_int " .. add, 1, true))
            assert.truthy(generated:find("TITAN_SOURCE_LOCAL ffi_int " .. accumulate,
                1, true))
            assert.truthy(csrc:find('/test.titan.h"', 1, true))
            assert.truthy(csrc:find("test_\\u2133_hidden_titan", 1, true))
            assert.falsy(csrc:find("titan_source_", 1, true))

            local pipe = assert(io.popen("nm test.o", "r"))
            local symbols = assert(pipe:read("*a"))
            assert.truthy(pipe:close())
            assert.truthy(symbols:find(
                coder._linkage_symbol_name(accumulate), 1, true), symbols)
            assert.falsy(symbols:find("\\u2133", 1, true), symbols)

            local ok, err = h.call("test", [[
                assert(test.exercise(4) == 29)
            ]])
            assert.truthy(ok, err)
        end)
    end)

    it("uses raw C scalar conditions, pointer truth, and evaluate-once calls",
    function()
        with_header([[
            typedef int ffi_int;
            static int ffi_counter = 0;
            static int ffi_next(void) { ffi_counter += 1; return ffi_counter; }
            static int ffi_counter_value(void) { return ffi_counter; }
            static int ffi_trace = 0;
            static int ffi_slots[2] = { 0, 0 };
            static void ffi_reset_trace(void) {
                ffi_trace = 0; ffi_slots[0] = 0; ffi_slots[1] = 0;
            }
            static int ffi_value(int digit, int value) {
                ffi_trace = ffi_trace * 10 + digit; return value;
            }
            static int *ffi_target(int digit, int index) {
                ffi_trace = ffi_trace * 10 + digit; return &ffi_slots[index];
            }
            static int ffi_trace_value(void) { return ffi_trace; }
            static int ffi_slot(int index) { return ffi_slots[index]; }
            typedef struct ffi_lvalue_holder {
                int *pointer;
                int index;
            } ffi_lvalue_holder;
            static ffi_lvalue_holder ffi_first_slot(void) {
                ffi_lvalue_holder holder;
                ffi_slots[0] = 0; ffi_slots[1] = 0;
                holder.pointer = &ffi_slots[0]; holder.index = 0;
                return holder;
            }
            static int ffi_retarget(ffi_lvalue_holder *holder) {
                holder->pointer = &ffi_slots[1]; return 9;
            }
            static int ffi_reindex(ffi_lvalue_holder *holder) {
                holder->index = 1; return 7;
            }
            typedef int (*ffi_callback)(int, int);
            typedef int (*ffi_unary_callback)(int);
            typedef void *ffi_void_pointer;
            static int ffi_old_callback(int value) { return 100 + value; }
            static int ffi_new_callback(int value) { return 200 + value; }
            static ffi_unary_callback ffi_get_callback(void) {
                return ffi_old_callback;
            }
            typedef struct ffi_callback_holder {
                ffi_unary_callback callback;
            } ffi_callback_holder;
            static ffi_callback_holder ffi_callback_holder_new(void) {
                ffi_callback_holder holder;
                holder.callback = ffi_old_callback;
                return holder;
            }
            static int ffi_retarget_callback(ffi_callback_holder *holder) {
                holder->callback = ffi_new_callback;
                return 7;
            }
            static int ffi_literals(_Bool flag, double number,
                                    const char *text) {
                return flag && number == 2.5 && text[0] == 'x';
            }
            static ffi_lvalue_holder *ffi_holder(void) {
                static ffi_lvalue_holder holder;
                holder.pointer = ffi_slots; holder.index = 1;
                return &holder;
            }
        ]], function(header)
            h.run_coder([[
                local c = foreign import "]] .. header .. [["

                foreign function raw(limit: c.ffi_int): c.ffi_int
                    local total = 0
                    local pointer: *c.ffi_int = nil
                    if pointer then total = 100 end
                    if limit then total = total + c.ffi_next() end
                    while total < limit do total = total + 1 end
                    repeat total = total - 1 until total == limit - 1
                    return total
                end

                foreign function sequence(): c.ffi_int
                    c.ffi_reset_trace()
                    local first, second =
                        c.ffi_value(1, 3), c.ffi_value(2, 4)
                    c.ffi_target(3, 0)[0], c.ffi_target(4, 1)[0] =
                        c.ffi_value(5, first), c.ffi_value(6, second)
                    return c.ffi_trace_value()
                        + c.ffi_slot(0) + c.ffi_slot(1)
                end

                foreign function prepared_pointer_target(): c.ffi_int
                    local holder = c.ffi_first_slot()
                    holder.pointer[0] = c.ffi_retarget(holder)
                    return c.ffi_slot(0) * 10 + c.ffi_slot(1)
                end

                foreign function prepared_index_target(): c.ffi_int
                    local holder = c.ffi_first_slot()
                    holder.pointer[holder.index] = c.ffi_reindex(holder)
                    return c.ffi_slot(0) * 10 + c.ffi_slot(1)
                end

                foreign function prepared_indirect_callee(): c.ffi_int
                    local holder = c.ffi_callback_holder_new()
                    return holder.callback(c.ffi_retarget_callback(holder))
                end

                foreign function roundtrip_pointer(
                    pointer: c.ffi_void_pointer
                ): c.ffi_int
                    local callback = pointer as c.ffi_unary_callback
                    return callback(1)
                end

                foreign function named(
                    left: c.ffi_int,
                    right: c.ffi_int
                ): c.ffi_int
                    return left * 10 + right
                end

                foreign function raw_forms(callback: c.ffi_callback): c.ffi_int
                    local negative: c.ffi_int = -1
                    local computed = callback(2, 5)
                    local selected: c.ffi_callback = named
                    local selected_value = selected(1, 2)
                    local holder = c.ffi_holder()
                    holder.pointer[holder.index] = 6
                    return named { right = computed, left = negative }
                        + c.ffi_literals(true, 2.5, "x")
                        + holder.pointer[holder.index] + selected_value
                end

                function exercise(): integer
                    return (raw(4) as integer) * 10
                        + (c.ffi_counter_value() as integer)
                end

                function sequencing(): integer
                    return sequence() as integer
                end

                function prepared_targets(): integer
                    return (prepared_pointer_target() as integer) * 10
                        + (prepared_index_target() as integer)
                end

                function forms(): integer
                    return raw_forms(named) as integer
                end

                function indirect_callee(): integer
                    return prepared_indirect_callee() as integer
                end

                function roundtrip(): integer
                    local pointer =
                        c.ffi_get_callback() as c.ffi_void_pointer
                    return roundtrip_pointer(pointer) as integer
                end
            ]], [[
                assert(test.exercise() == 31)
                assert(test.sequencing() == 123463)
                assert(test.prepared_targets() == 970)
                assert(test.forms() == 34)
                assert(test.indirect_callee() == 107)
                assert(test.roundtrip() == 101)
            ]])
        end)
    end)

    it("runs foreign floating numeric loops in both directions", function()
        with_header([[
            typedef double ffi_double;
        ]], function(header)
            h.run_coder([[
                local c = foreign import "]] .. header .. [["

                foreign function float_loops(): c.ffi_double
                    local total: c.ffi_double = 0.0
                    for up = 0.0, 1.0, 0.25 do
                        total = total + up
                    end
                    for down = 1.0, 0.0, -0.25 do
                        total = total + down
                    end
                    return total
                end

                function result(): float
                    return float_loops() as float
                end
            ]], [[
                assert(test.result() == 5.0)
            ]])
        end)
    end)

    it("renders the closed raw-C variable and inline-shape branches", function()
        local cmodule = types.CModule("fixture", {}, {})
        local ctx = coder._new_foreign_context({ module = "test" })
        local _, cname = coder._foreign_raw_var(ctx, {
            _tag = "Ast.VarDot",
            name = "C_VALUE",
            exp = { _type = cmodule },
            _type = types.CInteger("int", true, 3, 32),
        })
        assert.equal("C_VALUE", cname)

        local cint = types.CInteger("int", true, 3, 32)
        local size = { _tag = "Type.CPseudoSize", name = "sizeof", ctype = cint }
        local _, sizeof = coder._foreign_raw_var(ctx, {
            _tag = "Ast.VarDot",
            name = "sizeof",
            exp = { _type = cint },
            _decl = size,
            _type = cint,
        })
        assert.truthy(sizeof:find("sizeof", 1, true))

        local foreign = types.ModuleMember("other", "callback",
            types.CFunction({}, cint, false, false), {})
        foreign._foreign_source = true
        local _, reference = coder._foreign_raw_var(ctx, {
            _tag = "Ast.VarDot",
            name = "callback",
            exp = { _type = { _tag = "Type.Module" } },
            _decl = foreign,
            _type = foreign.type,
        })
        assert.equal(coder._foreign_func_name("other", "callback"), reference)

        assert.has_error(function()
            coder._foreign_raw_var(ctx, {
                _tag = "Ast.VarName", name = "missing",
            })
        end, "foreign variable lacks a C name: missing")
        assert.has_error(function()
            coder._foreign_raw_var(ctx, { _tag = "Ast.VarInvalid" })
        end, "unsupported foreign variable Ast.VarInvalid")

        local ret = { _tag = "Ast.StatReturn" }
        local block = function(stats)
            return { _tag = "Ast.StatBlock", stats = stats }
        end
        assert.is_true(coder._foreign_function_is_inline({
            block = block({ {
                _tag = "Ast.StatIf",
                thens = { { block = block({ ret }) } },
                elsestat = block({ ret }),
            } }),
        }))
        assert.is_true(coder._foreign_function_is_inline({
            block = block({ {
                _tag = "Ast.StatIf",
                thens = { { block = block({ ret }) } },
                elsestat = false,
            }, ret }),
        }))
    end)

    it("uses linkage spelling for native trace-name registry keys", function()
        local csrc = h.compile_and_read_c([[
            function visible(): integer
                return 1
            end
        ]])
        assert.truthy(csrc:find(
            'lua_setfield(L, -2, "test_\\342\\204\\263_visible_titan");',
            1, true))
        assert.falsy(csrc:find(
            'lua_setfield(L, -2, "test_\\\\u2133_visible_titan");',
            1, true))
    end)
end)
